package com.miguel.jarvis;
public final class PhoneMath {
    final String input;int pos;
    PhoneMath(String value){input=value;}
    double sum(){double n=product();while(pos<input.length()&&(input.charAt(pos)=='+'||input.charAt(pos)=='-')){char op=input.charAt(pos++);double right=product();n=op=='+'?n+right:n-right;}return n;}
    double product(){double n=atom();while(pos<input.length()&&(input.charAt(pos)=='*'||input.charAt(pos)=='/')){char op=input.charAt(pos++);double right=atom();if(op=='/'&&right==0)throw new IllegalArgumentException("No se puede dividir entre cero.");n=op=='*'?n*right:n/right;}return n;}
    double atom(){if(pos>=input.length())throw new IllegalArgumentException("Falta un número.");char c=input.charAt(pos++);if(c=='-')return -atom();if(c=='+')return atom();if(c=='('){double n=sum();if(pos>=input.length()||input.charAt(pos++)!=')')throw new IllegalArgumentException("Revisa los paréntesis.");return n;}int start=--pos;while(pos<input.length()&&(Character.isDigit(input.charAt(pos))||input.charAt(pos)=='.'))pos++;if(start==pos)throw new IllegalArgumentException("Revisa la operación.");return Double.parseDouble(input.substring(start,pos));}
    public static String answer(String text){String value=java.text.Normalizer.normalize(text.toLowerCase(java.util.Locale.ROOT),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[¿?¡!]","").replaceFirst("^(?:cuanto es|calcula|cuanto da) ","").replaceAll("\\bmas\\b","+").replaceAll("\\bmenos\\b","-").replaceAll("\\bpor\\b","*").replaceAll("\\bentre\\b","/").replace(',','.').replaceAll("\\s","");if(!value.matches("[0-9.+*/()-]+")||!value.matches(".*[+*/()-].*"))return null;if(value.length()>120)return "Divide el cálculo en pasos más pequeños.";try{PhoneMath parser=new PhoneMath(value);double result=parser.sum();if(parser.pos!=value.length())return "Revisa los signos de la operación.";if(!Double.isFinite(result)||Math.abs(result)>1e15)return "El cálculo supera el rango admitido.";return new java.text.DecimalFormat("0.##########").format(result);}catch(IllegalArgumentException error){return "No pude calcularlo: "+error.getMessage();}}
}
